rng = np.random.default_rng(3)
T, wo = 1000, 50
us = rng.uniform(0, 1, T)

rho2 = np.diag([1, 0]).astype(complex)
F = []
for u in us:
    rho2, f = step(rho2, u)
    F.append(f)
F = np.array(F)

def fit(F, y, lam):
    A = np.c_[F, np.ones(len(F))]
    G = A.T @ A + lam * np.eye(A.shape[1])
    G[-1, -1] -= lam
    return np.linalg.solve(G, A.T @ y)

def predict(F, w):
    return np.c_[F, np.ones(len(F))] @ w

def nmse(p, y):
    return float(np.sum((p - y) ** 2) / np.sum((y - y.mean()) ** 2))

train, test = slice(wo, 600), slice(600, 1000)
for d in range(5):
    y = np.roll(us, d)
    w = fit(F[train], y[train], 1e-6)
    print(d, round(nmse(predict(F[test], w), y[test]), 4))
